CREATE DATABASE IF NOT EXISTS coldchain; USE coldchain;
CREATE TABLE Users(id VARCHAR(10) PRIMARY KEY,name VARCHAR(80),email VARCHAR(100) UNIQUE,role VARCHAR(30),status VARCHAR(10));
CREATE TABLE Products(id VARCHAR(10) PRIMARY KEY,name VARCHAR(80),category VARCHAR(40),tmin DOUBLE,tmax DOUBLE,hmin DOUBLE,hmax DOUBLE);
CREATE TABLE Product_Batches(id VARCHAR(10) PRIMARY KEY,product_id VARCHAR(10),batch_no VARCHAR(30),mfd DATE,expiry DATE,qty INT,status VARCHAR(15),FOREIGN KEY(product_id) REFERENCES Products(id));
CREATE TABLE Vehicles(id VARCHAR(10) PRIMARY KEY,type VARCHAR(30),capacity VARCHAR(20),gps_device VARCHAR(20),cooling_status VARCHAR(10),status VARCHAR(15));
CREATE TABLE Drivers(id VARCHAR(10) PRIMARY KEY,name VARCHAR(80),phone VARCHAR(20),license_no VARCHAR(30),vehicle_id VARCHAR(10),status VARCHAR(10));
CREATE TABLE Shipments(id VARCHAR(10) PRIMARY KEY,product VARCHAR(80),source VARCHAR(40),destination VARCHAR(40),vehicle VARCHAR(10),driver VARCHAR(80),status VARCHAR(15),temperature DOUBLE,humidity DOUBLE,quality DOUBLE);
CREATE TABLE Sensor_Readings(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),temperature DOUBLE,humidity DOUBLE,door VARCHAR(8),cooling VARCHAR(8),lat DOUBLE,lng DOUBLE,ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shipment_id) REFERENCES Shipments(id));
CREATE TABLE Temperature_Log(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),value DOUBLE,severity VARCHAR(10),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Humidity_Log(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),value DOUBLE,severity VARCHAR(10),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Route_History(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),lat DOUBLE,lng DOUBLE,deviation BOOLEAN,ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Alerts(id VARCHAR(10) PRIMARY KEY,shipment_id VARCHAR(10),type VARCHAR(40),severity VARCHAR(10),assigned_to VARCHAR(80),status VARCHAR(15),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Risk_Assessment(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),spoilage INT,delay INT,compliance INT,ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Quality_Status(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipment_id VARCHAR(10),score DOUBLE,ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Reports(id BIGINT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(40),generated_by VARCHAR(10),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Login_Log(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(10),ip VARCHAR(40),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Audit_Log(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(10),action VARCHAR(60),module VARCHAR(40),description VARCHAR(200),ip VARCHAR(40),ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
